"""JSON transport and format validation for the offline Rust project."""
import json, math, os, pathlib, subprocess, sys

class Invalid(ValueError): pass

def need(ok):
    if not ok: raise Invalid('invalid')
def integer(x,lo,hi): need(type(x) is int and lo<=x<=hi)
def keys(x,names): need(type(x) is dict and set(x)==set(names.split()))
def seq(x,cap): need(type(x) is list and len(x)<=cap)
def pairs(items):
    result={}
    for k,v in items:
        need(k not in result);result[k]=v
    return result

def finite(s):
    x=float(s);need(math.isfinite(x));return x

def invalid_constant(s): raise Invalid('nonfinite')

def shape_topology(t):
    seq(t,8);need(t and type(t[0]) is str)
    mode=t[0];args=[0]*7
    if mode=='clos':
        need(len(t)==4);integer(t[1],4,18);need(t[1]%2==0 and t[2] in ['tor','pod']);integer(t[3],0,1)
        k=t[1];n=k*k;tors=n//2;templates=tors*(tors-1 if t[3] else tors-k//2);code=0;args[:3]=[k,int(t[2]=='pod'),t[3]]
    elif mode=='leaf-spine':
        need(len(t)==3);integer(t[1],2,256);integer(t[2],1,256);n=t[1]+t[2];templates=t[1]*(t[1]-1);code=1;args[:2]=t[1:]
    elif mode in ['torus2d','torus3d']:
        need(len(t)==3);integer(t[1],3,18);scope='row' if mode=='torus2d' else 'line';need(t[2] in ['host',scope]);n=t[1]**(2 if mode=='torus2d' else 3);templates=n*(n-1);code=2 if mode=='torus2d' else 3;args[:2]=[t[1],int(t[2]!='host')]
    elif mode=='dragonfly':
        need(len(t)==5)
        for x in t[1:4]:integer(x,1,64)
        g,a,h=t[1:4];need(g>=2 and g-1==a*h and t[4] in ['router','group','target']);n=g*a;templates=n*(n-1);code=4;args[:4]=[g,a,h,['router','group','target'].index(t[4])]
    elif mode=='dragonfly-plus':
        need(len(t)==7)
        for x in t[1:5]:integer(x,1,64)
        integer(t[5],0,1);g,l,s,h=t[1:5];need(g>=2 and (t[5] or g-1==s*h) and t[6] in ['tor','group']);n=g*(l+s);endpoints=g*l;templates=endpoints*(endpoints-1);code=5;args[:6]=[g,l,s,h,t[5],int(t[6]=='group')]
    else:raise Invalid('topology')
    need(n<=343)
    return code,args,n,templates

def transport(request):
    keys(request,'version sessions');integer(request['version'],2,2);seq(request['sessions'],16)
    words=[len(request['sessions'])];work=tasks_total=edits_total=queries_total=transactions_total=0
    def query(q,g,n,d):
        nonlocal queries_total
        keys(q,'groups nodes tasks')
        for k,cap in [('groups',g),('nodes',n),('tasks',d)]:
            seq(q[k],200000)
            for x in q[k]:integer(x,0,cap-1)
            words.extend([len(q[k]),*q[k]]);queries_total+=len(q[k])
    for s in request['sessions']:
        keys(s,'topology caps groups tasks query transactions')
        code,args,n,templates=shape_topology(s['topology']);seq(s['groups'],8192);need(s['groups']);g=len(s['groups']);seq(s['tasks'],100000);d=len(s['tasks'])
        seq(s['caps'],n);need(len(s['caps'])==n)
        for cap in s['caps']:integer(cap,0,10**9)
        words.extend([code,*args,d,g,*s['caps']])
        for row in s['groups']:
            seq(row,2);need(len(row)==2);integer(row[0],0,64);integer(row[1],1,10**12);words.extend(row)
        for row in s['tasks']:
            seq(row,5);need(len(row)==5)
            for x,lo,hi in zip(row,[0,0,1,0,0],[templates-1,g-1,10**9,10**9,1]):integer(x,lo,hi)
            words.extend(row)
        query(s['query'],g,n,d);seq(s['transactions'],50000);words.append(len(s['transactions']));transactions_total+=len(s['transactions'])
        ops=0
        for tx in s['transactions']:
            keys(tx,'revision edits query');integer(tx['revision'],0,10**9);seq(tx['edits'],100000);words.extend([tx['revision'],len(tx['edits'])]);ops+=len(tx['edits'])
            for edit in tx['edits']:
                seq(edit,3);need(len(edit)==3 and type(edit[0]) is str)
                op,idx,value=edit
                names=['move','weight','class','bind','pin','quota','budget','cap'];need(op in names)
                integer(idx,0,(d if op in names[:5] else g if op in ['quota','budget'] else n)-1)
                bounds={'move':(0,g-1),'weight':(1,10**9),'class':(0,10**9),'bind':(0,templates-1),'pin':(0,1),'quota':(0,64),'budget':(1,10**12),'cap':(0,10**9)}
                integer(value,*bounds[op]);words.extend([names.index(op),idx,value])
            query(tx['query'],g,n,d)
        tasks_total+=d;edits_total+=ops;work+=(templates+d+ops)*n
    work+=8*queries_total
    need(work<=128000000 and tasks_total<=200000 and edits_total<=100000 and queries_total<=200000 and transactions_total<=50000)
    return (' '.join(map(str,words))+'\n').encode()

def main():
    try:
        raw=sys.stdin.buffer.read(8*1024*1024+1);need(len(raw)<=8*1024*1024)
        text=raw.decode('utf-8');need(not text.startswith('\ufeff'))
        request=json.loads(text,object_pairs_hook=pairs,parse_constant=invalid_constant,parse_float=finite)
        data=transport(request)
    except (Invalid,ValueError,TypeError,KeyError,IndexError,RecursionError,OverflowError):
        print('{"error":"invalid"}');return
    base=pathlib.Path(__file__).resolve().parent
    subprocess.run(['sh',str(base/'build.sh')],check=True)
    binary=pathlib.Path(os.environ.get('TMPDIR','/workspace/tmp'))/'unit-merge-build/engine'
    result=subprocess.run([str(binary)],input=data,stdout=subprocess.PIPE,check=True)
    sys.stdout.buffer.write(result.stdout);sys.stdout.buffer.flush()

if __name__=='__main__':main()
"""Offline standard-library-only Rust build driver."""
import os,pathlib,subprocess
base=pathlib.Path(__file__).resolve().parent
out=pathlib.Path(os.environ.get('TMPDIR','/workspace/tmp'))/'unit-merge-build'
out.mkdir(parents=True,exist_ok=True)
env=os.environ.copy();env['LD_LIBRARY_PATH']='/opt/rust/lib'
flags=['/opt/rust/bin/rustc','--edition=2021','--target','x86_64-unknown-linux-musl','-C','opt-level=2','-C','codegen-units=1','-A','warnings']
subprocess.run(flags+['--crate-name','rust_unit_merge','--crate-type','rlib',str(base/'src/lib.rs'),'-o',str(out/'librust_unit_merge.rlib')],env=env,check=True)
subprocess.run(flags+['--crate-name','rust_unit_merge_cli','-C','link-arg=--threads=2','-C','linker=/opt/rust/lib/rustlib/x86_64-unknown-linux-gnu/bin/rust-lld',str(base/'src/main.rs'),'--extern','rust_unit_merge='+str(out/'librust_unit_merge.rlib'),'-o',str(out/'engine')],env=env,check=True)
#!/bin/sh
set -eu
exec python3 /workspace/submission/build.py

use std::io::{self, Read};
use rust_unit_merge::ledger::{Task,Edit,Query,Certificate,Ledger};
use rust_unit_merge::topology::*;

struct Input { words:Vec<String>, at:usize }
impl Input {
 fn next(&mut self)->Result<String,String> {if self.at>=self.words.len(){return Err("truncated".into());}let s=self.words[self.at].clone();self.at+=1;Ok(s)}
 fn n(&mut self)->Result<usize,String>{self.next()?.parse().map_err(|_|"integer".into())}
 fn u(&mut self)->Result<u64,String>{self.next()?.parse().map_err(|_|"integer".into())}
 fn ids(&mut self)->Result<Vec<usize>,String>{let n=self.n()?;(0..n).map(|_|self.n()).collect()}
 fn query(&mut self)->Result<Query,String>{Ok(Query{groups:self.ids()?,nodes:self.ids()?,tasks:self.ids()?})}
}
fn topology(i:&mut Input)->Result<TopologyCase,String>{
 let code=i.n()?; let args=(0..7).map(|_|i.n()).collect::<Result<Vec<_>,_>>()?;
 Ok(match code {
  0=>build_clos(args[0],1,None,None,args[2]!=0,if args[1]==0 {ClosSourceGroupScope::Tor}else{ClosSourceGroupScope::Pod}),
  1=>build_leaf_spine(args[0],args[1],1),
  2=>build_torus2d(args[0],1,if args[1]==0 {Torus2DSourceGroupScope::Host}else{Torus2DSourceGroupScope::Row}),
  3=>build_torus3d(args[0],1,if args[1]==0 {Torus3DSourceGroupScope::Host}else{Torus3DSourceGroupScope::Line}),
  4=>build_dragonfly(args[0],args[1],args[2],Some(1),1.0,1,0,match args[3]{0=>DragonflySourceGroupScope::Router,1=>DragonflySourceGroupScope::Group,_=>DragonflySourceGroupScope::SourceTargetGroup}),
  5=>build_dragonfly_plus(args[0],args[1],args[2],args[3],args[4]!=0,1,0,if args[5]==0{DragonflyPlusSourceGroupScope::Tor}else{DragonflyPlusSourceGroupScope::Group}),
  _=>return Err("topology".into()),
 })
}
fn array<T:std::fmt::Display>(row:&[T])->String{format!("[{}]",row.iter().map(|x|x.to_string()).collect::<Vec<_>>().join(","))}
fn rows<T:std::fmt::Display,const N:usize>(data:&[[T;N]])->String{format!("[{}]",data.iter().map(|x|array(x)).collect::<Vec<_>>().join(","))}
fn certificate(c:Certificate)->String{format!("{{\"totals\":{},\"groups\":{},\"nodes\":{},\"tasks\":{}}}",array(&c.totals),rows(&c.groups),rows(&c.nodes),rows(&c.tasks))}
fn run(i:&mut Input)->Result<String,String>{
 let sessions=i.n()?;let mut output=Vec::new();
 for _ in 0..sessions {
  let case=topology(i)?;let task_count=i.n()?;let group_count=i.n()?;
  let caps=(0..case.problem.num_nodes).map(|_|i.u()).collect::<Result<Vec<_>,_>>()?;
  let mut quotas=Vec::new();let mut budgets=Vec::new();
  for _ in 0..group_count{quotas.push(i.u()?);budgets.push(i.u()?);}
  let mut tasks=Vec::new();
  for _ in 0..task_count{tasks.push(Task{template:i.n()?,group:i.n()?,weight:i.u()?,class:i.u()?,pinned:i.n()?!=0});}
  let mut ledger=Ledger::new(&case.problem,tasks,quotas,budgets,caps)?;
  let initial=certificate(ledger.certificate(&i.query()?));
  let transactions=i.n()?;let mut results=Vec::new();
  for _ in 0..transactions{
   let expected=i.u()?;let operations=i.n()?;let mut edits=Vec::new();
   for _ in 0..operations{
    let op=i.n()?;let id=i.n()?;let value=i.u()?;
    edits.push(match op{0=>Edit::Move(id,value as usize),1=>Edit::Weight(id,value),2=>Edit::Class(id,value),3=>Edit::Bind(id,value as usize),4=>Edit::Pin(id,value!=0),5=>Edit::Quota(id,value),6=>Edit::Budget(id,value),7=>Edit::Cap(id,value),_=>return Err("operation".into())});
   }
   let result=ledger.transact(expected,&edits,&i.query()?);
   results.push(format!("{{\"accepted\":{},\"revision\":{},\"violations\":{},\"certificate\":{}}}",result.accepted,result.revision,result.violations.map(|x|array(&x)).unwrap_or_else(||"null".into()),certificate(result.certificate)));
  }
  output.push(format!("{{\"nodes\":{},\"templates\":{},\"initial\":{},\"transactions\":[{}]}}",case.problem.num_nodes,case.problem.demands.len(),initial,results.join(",")));
 }
 if i.at!=i.words.len(){return Err("extra".into());}
 Ok(format!("{{\"sessions\":[{}]}}",output.join(",")))
}
fn main(){
 let mut raw=String::new();io::stdin().read_to_string(&mut raw).unwrap();
 let mut i=Input{words:raw.split_whitespace().map(str::to_string).collect(),at:0};
 match run(&mut i){Ok(out)=>println!("{}",out),Err(_)=>println!("{{\"error\":\"invalid\"}}")}
}
