                    load -= d.weight0;
                    pinned -= d.pinned0 as i64;
                    *pairs.entry((self.domain[t0], d.class0)).or_insert(0) -= 1;
                    if !(d.group1 as usize == g && d.template1 == d.template0) {
                        for node in fp_nodes(&self.footprint[t0]) {
                            cover[node] -= 1;
                        }
                    }
                }
                if d.group1 as usize == g {
                    count += 1;
                    load += d.weight1;
                    pinned += d.pinned1 as i64;
                    *pairs.entry((self.domain[t1], d.class1)).or_insert(0) += 1;
                    if !(d.group0 as usize == g && d.template1 == d.template0) {
                        for node in fp_nodes(&self.footprint[t1]) {
                            cover[node] += 1;
                        }
                    }
                }
            }
            let mut distinct_pairs = 0usize;
            let mut single_pair = (0u64, 0u64);
            for (&pair, &cnt) in pairs.iter() {
                if cnt > 0 {
                    distinct_pairs += 1;
                    single_pair = pair;
                }
            }
            if distinct_pairs > 1 {
                mixed += 1;
            }
            let mut fp_size = 0u32;
            for node in 0..n {
                if cover[node] > 0 {
                    fp_size += 1;
                }
            }
            if count > 0 && (quota1 == 0 || load > quota1.saturating_mul(budget1)) {
                work += 1;
            }
            let reserve0 = if count0 > 0 { quota0 } else { 0 };
            let reserve1 = if count > 0 { quota1 } else { 0 };
            for node in 0..n {
                let old = if cover_is(self, g, node) > 0 { reserve0 } else { 0 };
                let new = if cover[node] > 0 { reserve1 } else { 0 };
                usage_delta[node] += new as i64 - old as i64;
            }
            scratch_cover.push(cover);
            scratch_count.push(count);
            scratch_load.push(load);
            scratch_pinned.push(pinned);
            scratch_fp_size.push(fp_size);
            scratch_pair.push(single_pair);
        }

        // Over-capacity nodes in the proposal.
        let mut capacity = 0u64;
        for node in 0..n {
            let usage = self.node_usage[node] as i64 + usage_delta[node];
            let cap = cap_edits.get(&node).copied().unwrap_or(self.node_capacity[node]);
            if usage > cap as i64 {
                capacity += 1;
            }
        }

        // Pin violations: tasks pinned at the beginning of the transaction
        // protect group, template, weight, class and their old group's quota.
        let quota_changed: HashSet<usize> = quota_edits
            .iter()
            .filter(|(&g, &q)| q != self.group_quota[g])
            .map(|(&g, _)| g)
            .collect();
        let mut pins = 0u64;
        for &g in &quota_changed {
            pins += self.group_pinned[g] as u64;
        }
        for d in &deltas {
            if !d.pinned0 {
                continue;
            }
            let fields_changed = d.group0 != d.group1
                || d.template0 != d.template1
                || d.weight0 != d.weight1
                || d.class0 != d.class1;
            if fields_changed && !quota_changed.contains(&(d.group0 as usize)) {
                pins += 1;
            }
        }

        let violations = [capacity, mixed, work, pins];
        let accepted = violations == [0, 0, 0, 0];

        if accepted {
            // Commit the proposal atomically.
            let mut weight_delta = 0i64;
            let mut pins_delta = 0i64;
            for d in &deltas {
                let t = d.task;
                self.task_template[t] = d.template1;
                self.task_group[t] = d.group1;
                self.task_weight[t] = d.weight1;
                self.task_class[t] = d.class1;
                self.task_pinned[t] = d.pinned1;
                weight_delta += d.weight1 as i64 - d.weight0 as i64;
                pins_delta += d.pinned1 as i64 - d.pinned0 as i64;
            }
            self.total_weight = (self.total_weight as i64 + weight_delta) as u64;
            self.total_pins = (self.total_pins as i64 + pins_delta) as u64;
            for (j, &g) in group_list.iter().enumerate() {
                if let Some(&q) = quota_edits.get(&g) {
                    self.group_quota[g] = q;
                }
                if let Some(&b) = budget_edits.get(&g) {
                    self.group_budget[g] = b;
                }
                let count0 = self.group_count[g];
                let count1 = scratch_count[j];
                if count0 == 0 && count1 > 0 {
                    self.total_active += 1;
                } else if count0 > 0 && count1 == 0 {
                    self.total_active -= 1;
                }
                self.group_count[g] = count1;
                self.group_load[g] = scratch_load[j];
                self.group_fp_size[g] = scratch_fp_size[j];
                self.group_pinned[g] = scratch_pinned[j];
                if count1 > 0 {
                    self.group_domain[g] = scratch_pair[j].0;
                    self.group_class[g] = scratch_pair[j].1;
                } else {
                    self.group_domain[g] = 0;
                    self.group_class[g] = 0;
                }
                std::mem::swap(&mut self.group_cover[g], &mut scratch_cover[j]);
            }
            let mut slots_delta = 0i64;
            for node in 0..n {
                self.node_usage[node] = (self.node_usage[node] as i64 + usage_delta[node]) as u64;
                slots_delta += usage_delta[node];
            }
            self.total_slots = (self.total_slots as i64 + slots_delta) as u64;
            for (&v, &c) in cap_edits.iter() {
                self.node_capacity[v] = c;
            }
            self.revision += 1;
        }

        let certificate = self.certificate(query);
        Outcome {
            accepted,
            revision: self.revision,
            violations: Some(violations),
            certificate,
        }
    }
}

// Helper used above to read the committed cover count of a group's node.
fn cover_is(ledger: &Ledger, g: usize, node: usize) -> u32 {
    ledger.group_cover[g][node]
}
