    ['dragonfly-plus', 3, 1, 2, 1, 1, 'tor'], ['dragonfly-plus', 3, 2, 2, 1, 0, 'group'],
]

def main():
    seed = int(sys.argv[1]) if len(sys.argv) > 1 else 1
    rounds = int(sys.argv[2]) if len(sys.argv) > 2 else 200
    rng = random.Random(seed)
    fails = 0
    checked = 0
    for i in range(rounds):
        topo = TOPOS[i % len(TOPOS)]
        session = gen_session(rng, topo)
        if session is None: continue
        expected = run_ref(session)
        got = run_engine(session)
        checked += 1
        if got != expected:
            fails += 1
            print(f'ROUND {i} topo={topo} MISMATCH')
            print('REQ:', json.dumps({'version': 2, 'sessions': [session]})[:2000])
            # find first difference
            print('EXP:', json.dumps(expected)[:1500])
            print('GOT:', json.dumps(got)[:1500])
            if fails >= 3: break
    print(f'checked={checked} fails={fails}')

if __name__ == '__main__':
    main()
