"""Replicate public_check.execute() as closely as this worker profile permits:
candidate_setup policy/rlimits + real pipes + strict JSON load + fixtures + fuzz batches."""
import json, math, os, selectors, subprocess, sys
from candidate_policy import candidate_setup

def pairs(items):
    obj = {}
    for key, val in items:
        if key in obj: raise ValueError('duplicate output key')
        obj[key] = val
    return obj

def nonfinite(value): raise ValueError('nonfinite output')

def finite_float(value):
    parsed = float(value)
    if not math.isfinite(parsed): raise ValueError('nonfinite output')
    return parsed

def strict_load(raw):
    return json.loads(raw.decode('utf-8'), object_pairs_hook=pairs,
                      parse_constant=nonfinite, parse_float=finite_float)

def same(a, b):
    if type(a) is not type(b): return False
    if isinstance(a, dict):
        return a.keys() == b.keys() and all(same(a[k], b[k]) for k in a)
    if isinstance(a, list):
        return len(a) == len(b) and all(same(x, y) for x, y in zip(a, b))
    return a == b

def execute(candidate, data):
    env = {'PATH': os.environ.get('PATH', '/usr/local/bin:/usr/bin:/bin'),
           'LANG': 'C.UTF-8', 'HOME': '/workspace',
           'TMPDIR': os.environ.get('TMPDIR', '/workspace/tmp'),
           'PYTHONDONTWRITEBYTECODE': '1', 'PYTHONHASHSEED': '0',
           'OPENBLAS_NUM_THREADS': '1', 'OMP_NUM_THREADS': '1', 'MKL_NUM_THREADS': '1'}
    p = subprocess.Popen([sys.executable, '-B', str(candidate)], stdin=subprocess.PIPE,
                         stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                         close_fds=True, env=env, preexec_fn=candidate_setup)
    out, err = p.communicate(data)
    assert p.returncode == 0, f'nonzero exit {p.returncode}: {err[-1000:]}'
    assert out.strip(), 'empty output'
    assert len(out) <= 32*1024**2, 'stdout cap'
    assert len(err) <= 1024**2, 'stderr cap'
    return strict_load(out)

def main():
    candidate = 'submission/main.py'
    fixtures = json.load(open('examples/checks.json'))
    for i, fixture in enumerate(fixtures):
        data = fixture.get('raw')
        if data is None:
            data = json.dumps(fixture['request'], separators=(',', ':'))
        result = execute(candidate, data.encode('utf-8'))
        assert same(result, fixture['response']), f'fixture {i} mismatch: {json.dumps(result)[:400]}'
        print(f'fixture {i}: PASS')
    # fuzz batches through the policy-exact executor
    import runpy
    sys.argv = ['ref_check', '101', '200']
    sys.path.insert(0, 'scratch')
    import ref_check
    ref_check.run_engine_orig = ref_check.run_engine
    def policy_engine(sessions):
        req = {'version': 2, 'sessions': sessions}
        data = json.dumps(req, separators=(',', ':'))
        try:
            return execute(candidate, data.encode())
        except Exception as e:
            return {'BADOUTPUT': [str(e)]}
    ref_check.run_engine = policy_engine
    ref_check.main()
    print('ALL POLICY-EXACT CHECKS DONE')

if __name__ == '__main__':
    main()
