use crate::solver::SolverProblem;
use std::collections::{HashMap, HashSet};

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Task {
    pub template: usize,
    pub group: usize,
    pub weight: u64,
    pub class: u64,
    pub pinned: bool,
}

#[derive(Clone, Debug)]
pub enum Edit {
    Move(usize, usize), Weight(usize, u64), Class(usize, u64), Bind(usize, usize),
    Pin(usize, bool), Quota(usize, u64), Budget(usize, u64), Cap(usize, u64),
}

#[derive(Clone, Default)]
pub struct Query { pub groups: Vec<usize>, pub nodes: Vec<usize>, pub tasks: Vec<usize> }

pub struct Certificate {
    pub totals: [u64; 4],
    pub groups: Vec<[i64; 8]>,
    pub nodes: Vec<[u64; 3]>,
    pub tasks: Vec<[u64; 6]>,
}

pub struct Outcome {
    pub accepted: bool,
    pub revision: u64,
    pub violations: Option<[u64; 4]>,
    pub certificate: Certificate,
}

// The transactional certificate layer described in PROTOCOL.md.
//
// The committed state is always legal: the initial configuration is checked at
// construction time and only proposals whose four exact proposed-state
// violation counts are all zero are committed. Rejected proposals (including
// stale revisions) never touch any committed value.
//
// A template footprint is the set of cache-bearing nodes on all shortest
// routes of its endpoints; the supplied topology module already materialises
// those node sets in SolverProblem::demands. The template domain is the
// demand merge class when present (Dragonfly source/target-group scope) and
// otherwise the source merge group containing the demand source.

const FP_WORDS: usize = 6; // num_nodes <= 343 < 6 * 64

#[derive(Clone, Copy)]
struct TaskEdit {
    template: u32,
    group: u32,
    weight: u64,
    class: u64,
    pinned: bool,
}

struct TaskDelta {
    task: usize,
    template0: u32,
    template1: u32,
    group0: u32,
    group1: u32,
    weight0: u64,
    weight1: u64,
    class0: u64,
    class1: u64,
    pinned0: bool,
    pinned1: bool,
}

pub struct Ledger {
    num_nodes: usize,
    footprint: Vec<[u64; FP_WORDS]>,
    domain: Vec<u64>,
    // committed task fields
    task_template: Vec<u32>,
    task_group: Vec<u32>,
    task_weight: Vec<u64>,
    task_class: Vec<u64>,
    task_pinned: Vec<bool>,
    // committed group fields
    group_quota: Vec<u64>,
    group_budget: Vec<u64>,
    // committed group aggregates
    group_count: Vec<i64>,
    group_load: Vec<u64>,
    group_fp_size: Vec<u32>,
    group_domain: Vec<u64>,
    group_class: Vec<u64>,
    group_pinned: Vec<i64>,
    group_cover: Vec<Vec<u32>>,
    // committed node fields and aggregates
    node_capacity: Vec<u64>,
    node_usage: Vec<u64>,
    // committed certificate totals
    total_active: u64,
    total_slots: u64,
    total_weight: u64,
    total_pins: u64,
    revision: u64,
}

fn fp_nodes(bits: &[u64; FP_WORDS]) -> impl Iterator<Item = usize> + '_ {
    (0..FP_WORDS).flat_map(move |w| {
        let mut word = bits[w];
        std::iter::from_fn(move || {
            if word == 0 {
                return None;
            }
            let b = word.trailing_zeros() as usize;
            word &= word - 1;
            Some(w * 64 + b)
        })
    })
}

impl Ledger {
    pub fn new(
        problem: &SolverProblem,
        tasks: Vec<Task>,
        quotas: Vec<u64>,
        budgets: Vec<u64>,
        capacities: Vec<u64>,
    ) -> Result<Self, String> {
        let n = problem.num_nodes;
        let num_groups = quotas.len();
        if budgets.len() != num_groups || capacities.len() != n {
            return Err("invalid".into());
        }
        let num_templates = problem.demands.len();
        let mut source_index = vec![usize::MAX; n];
        for (gi, nodes) in problem.source_merge_groups.iter().enumerate() {
            for &node in nodes {
                if node < n {
                    source_index[node] = gi;
                }
            }
        }
        let mut footprint = vec![[0u64; FP_WORDS]; num_templates];
        let mut domain = vec![0u64; num_templates];
        for (ti, demand) in problem.demands.iter().enumerate() {
            for &node in &demand.footprint {
                if node < n {
                    footprint[ti][node / 64] |= 1u64 << (node % 64);
                }
            }
            domain[ti] = match &problem.demand_merge_classes {
                Some(classes) if ti < classes.len() => classes[ti] as u64,
                _ => {
                    if demand.src < n && source_index[demand.src] != usize::MAX {
                        source_index[demand.src] as u64
                    } else {
                        demand.src as u64
                    }
                }
            };
        }

    }

    let mut ledger = Ledger {
        num_nodes: n,
        footprint,
        domain,
        task_template: vec![0; tasks.len()],
        task_group: vec![0; tasks.len()],
        task_weight: vec![0; tasks.len()],
        task_class: vec![0; tasks.len()],
        task_pinned: vec![false; tasks.len()],
        group_quota: quotas,
        group_budget: budgets,
        group_count: vec![0; num_groups],
        group_load: vec![0; num_groups],
        group_fp_size: vec![0; num_groups],
        group_domain: vec![0; num_groups],
        group_class: vec![0; num_groups],
        group_pinned: vec![0; num_groups],
        group_cover: vec![vec![0u32; n]; num_groups],
        node_capacity: capacities,
        node_usage: vec![0; n],
        total_active: 0,
        total_slots: 0,
        total_weight: 0,
        total_pins: 0,
        revision: 0,
    };

    for (tid, task) in tasks.iter().enumerate() {
        if task.template >= num_templates || task.group >= num_groups {
            return Err("invalid".into());
        }
        ledger.task_template[tid] = task.template as u32;
        ledger.task_group[tid] = task.group as u32;
        ledger.task_weight[tid] = task.weight;
        ledger.task_class[tid] = task.class;
        ledger.task_pinned[tid] = task.pinned;
        let g = task.group;
        let pair = (ledger.domain[task.template], task.class);
        if ledger.group_count[g] == 0 {
            ledger.group_domain[g] = pair.0;
            ledger.group_class[g] = pair.1;
        } else if (ledger.group_domain[g], ledger.group_class[g]) != pair {
            // a mixed group makes the initial configuration illegal
            return Err("invalid".into());
        }
        ledger.group_count[g] += 1;
        ledger.group_load[g] += task.weight;
        if task.pinned {
            ledger.group_pinned[g] += 1;
            ledger.total_pins += 1;
        }
        ledger.total_weight += task.weight;
        let bits = ledger.footprint[task.template];
        for node in fp_nodes(&bits) {
            let cover = &mut ledger.group_cover[g][node];
            if *cover == 0 {
                ledger.group_fp_size[g] += 1;
            }
            *cover += 1;
        }
    }

    for g in 0..num_groups {
        if ledger.group_count[g] == 0 {
            continue;
        }
        ledger.total_active += 1;
        if ledger.group_quota[g] == 0 {
            return Err("invalid".into());
        }
        if ledger.group_load[g] > ledger.group_quota[g].saturating_mul(ledger.group_budget[g]) {
            return Err("invalid".into());
        }
        let quota = ledger.group_quota[g];
        for node in 0..n {
            if ledger.group_cover[g][node] > 0 {
                ledger.node_usage[node] += quota;
            }
        }
    }
    for node in 0..n {
        if ledger.node_usage[node] > ledger.node_capacity[node] {
            return Err("invalid".into());
        }
        ledger.total_slots += ledger.node_usage[node];
    }
    Ok(ledger)
}

pub fn certificate(&self, query: &Query) -> Certificate {
    let mut groups = Vec::with_capacity(query.groups.len());
    for &g in &query.groups {
        let (dom, cls) = if self.group_count[g] > 0 {
            (self.group_domain[g] as i64, self.group_class[g] as i64)
        } else {
            (-1i64, -1i64)
        };
        groups.push([
            g as i64,
            self.group_count[g],
            self.group_load[g] as i64,
            self.group_quota[g] as i64,
            self.group_budget[g] as i64,
            self.group_fp_size[g] as i64,
            dom,
            cls,
        ]);
    }
    let mut nodes = Vec::with_capacity(query.nodes.len());
    for &v in &query.nodes {
        nodes.push([v as u64, self.node_usage[v], self.node_capacity[v]]);
    }
    let mut tasks = Vec::with_capacity(query.tasks.len());
    for &t in &query.tasks {
        tasks.push([
            t as u64,
            self.task_group[t] as u64,
            self.task_template[t] as u64,
            self.task_weight[t],
            self.task_class[t],
            self.task_pinned[t] as u64,
        ]);
    }
    Certificate {
        totals: [self.total_active, self.total_slots, self.total_weight, self.total_pins],
        groups,
        nodes,
        tasks,
    }
}

fn snapshot_task(&self, t: usize) -> TaskEdit {
    TaskEdit {
        template: self.task_template[t],
        group: self.task_group[t],
        weight: self.task_weight[t],
        class: self.task_class[t],
        pinned: self.task_pinned[t],
    }
}

pub fn transact(&mut self, expected: u64, edits: &[Edit], query: &Query) -> Outcome {
    if expected != self.revision {
        // Stale proposals produce no speculative state and no violations.
        let certificate = self.certificate(query);
        return Outcome {
            accepted: false,
            revision: self.revision,
            violations: None,
            certificate,
        };
    }

    // Final values: plain field assignments, repeated ones keep the last value.
    let mut task_edits: HashMap<usize, TaskEdit> = HashMap::new();
    let mut quota_edits: HashMap<usize, u64> = HashMap::new();
    let mut budget_edits: HashMap<usize, u64> = HashMap::new();
    let mut cap_edits: HashMap<usize, u64> = HashMap::new();
    for edit in edits {
        match *edit {
            Edit::Move(t, g) => {
                task_edits.entry(t).or_insert_with(|| self.snapshot_task(t)).group = g as u32;
            }
            Edit::Weight(t, w) => {
                task_edits.entry(t).or_insert_with(|| self.snapshot_task(t)).weight = w;
            }
            Edit::Class(t, c) => {
                task_edits.entry(t).or_insert_with(|| self.snapshot_task(t)).class = c;
            }
            Edit::Bind(t, tpl) => {
                task_edits.entry(t).or_insert_with(|| self.snapshot_task(t)).template = tpl as u32;
            }
            Edit::Pin(t, p) => {
                task_edits.entry(t).or_insert_with(|| self.snapshot_task(t)).pinned = p;
            }
            Edit::Quota(g, q) => {
                quota_edits.insert(g, q);
            }
            Edit::Budget(g, b) => {
                budget_edits.insert(g, b);
            }
            Edit::Cap(v, c) => {
                cap_edits.insert(v, c);
            }
        }
    }

    // Net per-task changes between the committed state and the proposal.
    let mut deltas: Vec<TaskDelta> = Vec::with_capacity(task_edits.len());
    for (&t, final_state) in task_edits.iter() {
        deltas.push(TaskDelta {
            task: t,
            template0: self.task_template[t],
            template1: final_state.template,
            group0: self.task_group[t],
            group1: final_state.group,
            weight0: self.task_weight[t],
            weight1: final_state.weight,
            class0: self.task_class[t],
            class1: final_state.class,
            pinned0: self.task_pinned[t],
            pinned1: final_state.pinned,
        });
    }

    // Groups whose proposal aggregates may differ from the committed ones.
    let mut group_pos: HashMap<usize, usize> = HashMap::new();
    let mut group_list: Vec<usize> = Vec::new();
    {
        let mut touch = |g: usize| {
            group_pos.entry(g).or_insert_with(|| {
                group_list.push(g);
                group_list.len() - 1
            });
        };
        for d in &deltas {
            touch(d.group0 as usize);
            touch(d.group1 as usize);
        }
        for &g in quota_edits.keys() {
            touch(g);
        }
        for &g in budget_edits.keys() {
            touch(g);
        }
    }
    let mut group_deltas: Vec<Vec<u32>> = vec![Vec::new(); group_list.len()];
    for (i, d) in deltas.iter().enumerate() {
        group_deltas[group_pos[&(d.group0 as usize)]].push(i as u32);
        if d.group1 != d.group0 {
            group_deltas[group_pos[&(d.group1 as usize)]].push(i as u32);
        }
    }

    // Proposal aggregates per touched group plus node usage deltas.
    let n = self.num_nodes;
    let mut usage_delta = vec![0i64; n];
    let mut scratch_cover: Vec<Vec<u32>> = Vec::with_capacity(group_list.len());
    let mut scratch_count: Vec<i64> = Vec::with_capacity(group_list.len());
    let mut scratch_load: Vec<u64> = Vec::with_capacity(group_list.len());
    let mut scratch_pinned: Vec<i64> = Vec::with_capacity(group_list.len());
    let mut scratch_fp_size: Vec<u32> = Vec::with_capacity(group_list.len());
    let mut scratch_pair: Vec<(u64, u64)> = Vec::with_capacity(group_list.len());
    let mut mixed = 0u64;
    let mut work = 0u64;

    for (j, &g) in group_list.iter().enumerate() {
        let count0 = self.group_count[g];
        let quota0 = self.group_quota[g];
        let budget0 = self.group_budget[g];
        let quota1 = quota_edits.get(&g).copied().unwrap_or(quota0);
        let budget1 = budget_edits.get(&g).copied().unwrap_or(budget0);
        let mut cover = self.group_cover[g].clone();
        let mut count = count0;
        let mut load = self.group_load[g];
        let mut pinned = self.group_pinned[g];
        // The committed group is uniform in (domain, class); proposal pairs
        // are tracked with exact counts over the final membership.
        let mut pairs: HashMap<(u64, u64), i64> = HashMap::new();

    let mut pairs: HashMap<(u64, u64), i64> = HashMap::new();
    if count0 > 0 {
        pairs.insert((self.group_domain[g], self.group_class[g]), count0);
    }
    for &i in &group_deltas[j] {
        let d = &deltas[i as usize];
        let t0 = d.template0 as usize;
        let t1 = d.template1 as usize;
        if d.group0 as usize == g {
            count -= 1;
            load -= d.weight0;
            pinned -= d.pinned0 as i64;
            *pairs.entry((self.domain[t0], d.class0)).or_insert(0) -= 1;
            if !(d.group1 as usize == g && d.template1 == d.template0) {
                for node in fp_nodes(&self.footprint[t0]) {
                    cover[node] -= 1;
                }
            }
        }
        if d.group1 as usize == g {
            count += 1;
            load += d.weight1;
            pinned += d.pinned1 as i64;
            *pairs.entry((self.domain[t1], d.class1)).or_insert(0) += 1;
            if !(d.group0 as usize == g && d.template1 == d.template0) {
                for node in fp_nodes(&self.footprint[t1]) {
                    cover[node] += 1;
                }
            }
        }
    }
    let mut distinct_pairs = 0usize;
    let mut single_pair = (0u64, 0u64);
    for (&pair, &cnt) in pairs.iter() {
        if cnt > 0 {
            distinct_pairs += 1;
            single_pair = pair;
        }
    }
    if distinct_pairs > 1 {
        mixed += 1;
    }
    let mut fp_size = 0u32;
    for node in 0..n {
        if cover[node] > 0 {
            fp_size += 1;
        }
    }
    if count > 0 && (quota1 == 0 || load > quota1.saturating_mul(budget1)) {
        work += 1;
    }
    let reserve0 = if count0 > 0 { quota0 } else { 0 };
    let reserve1 = if count > 0 { quota1 } else { 0 };
    for node in 0..n {
        let old = if self.group_cover[g][node] > 0 { reserve0 } else { 0 };
        let new = if cover[node] > 0 { reserve1 } else { 0 };
        usage_delta[node] += new as i64 - old as i64;
    }
    scratch_cover.push(cover);
    scratch_count.push(count);
    scratch_load.push(load);
    scratch_pinned.push(pinned);
    scratch_fp_size.push(fp_size);
    scratch_pair.push(single_pair);
}

